cd /tmp/<path>; ls; cat > /tmp/sim.py <<'E'
import sys,re
prog=[]
for l in open('prog.pw9'):
    l=l.split(';')[0].strip()
    if l: prog.append(l.split())
R={'a':0,'b':0,'c':0,'d':0}
def v(x): return R[x] if x in R else int(x)
pc=0;n=0;s=0
while 0<=pc<len(prog):
    i=prog[pc];op=i[0];n+=1;nx=pc+1
    if op=='set':R[i[1]]=v(i[2])%65536
    elif op=='add':R[i[1]]=(R[i[1]]+v(i[2]))%65536
    elif op=='mul':R[i[1]]=(R[i[1]]*v(i[2]))%65536
    elif op=='mod':
        x=v(i[2])
        if x>0:R[i[1]]%=x
    elif op=='dec':R[i[1]]=max(0,R[i[1]]-1)
    elif op=='jnz':
        if v(i[1])!=0:nx=pc+v(i[2])
    elif op=='skp':
        if v(i[1])<v(i[2]):nx=pc+2
    elif op=='out':s+=v(i[1])
    else: raise Exception(i)
    pc=nx
print(s,n)
open('answer.txt','w').write(f"{s} {n}\n")
E
python3 -I /tmp/sim.py
